keys=sorted(M,key=len,reverse=True)
def fixf(v):
    for k in keys:
        v=re.sub(r"(?<![A-Z0-9_])'?%s'?!"%re.escape(k), lambda m: "'%s'!"%M[k] if "'" in m.group(0) else M[k]+"!", v)
